#include <cstdio>
using namespace std;

#define For(i, a, b) for (int i = (a); i <= (b); i++)
#define Forn(i, a, b) for (int i = (a); i >= (b); i--)

inline int read() {
    int x = 0, f = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x * f;
}

const int N = 1010;
int n;
int a[N], flag[N], reflag[N];

int main() {
    n = read();
    For(i, 1, n) a[i] = read();

    Forn(i, n, 1) {
        if (reflag[a[i]]) flag[i] = 1;
        reflag[a[i]] = 1;
    }

    int ans = 0;
    For(i, 1, n) {
        if (!flag[i]) ans++;
    }

    printf("%d\n", ans);
    For(i, 1, n) {
        if (!flag[i]) printf("%d ", a[i]);
    }
    return 0;
}

